package com.ds.goroute.controller;
import com.ds.goroute.dto.BaseResponse;import com.ds.goroute.dto.response.*;import com.ds.goroute.service.ActivityCommerceService;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;import java.util.*;
@RestController @RequestMapping("/v1/api/public/marketplace-activities") @RequiredArgsConstructor
public class PublicActivityCommerceController {private final ActivityCommerceService s;@GetMapping public ResponseEntity<BaseResponse<List<MarketplaceActivityResponse>>> list(@RequestParam(required=false)String q,@RequestParam(required=false)String kind,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.listPublic(q,kind,page,size)));}@GetMapping("/{id}")public ResponseEntity<BaseResponse<MarketplaceActivityResponse>> get(@PathVariable UUID id){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.getPublic(id)));}@GetMapping("/{id}/similar")public ResponseEntity<BaseResponse<List<MarketplaceActivityResponse>>> similar(@PathVariable UUID id,@RequestParam(defaultValue="6")int size){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.listSimilarPublic(id,size)));}
@GetMapping("/{id}/availability")public ResponseEntity<BaseResponse<List<ActivityAvailabilityDayResponse>>> availability(@PathVariable UUID id,@RequestParam(required=false)@org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE)java.time.LocalDate from,@RequestParam(defaultValue="60")int days){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.availabilityPublic(id,from,days)));}
@GetMapping("/{id}/packages")public ResponseEntity<BaseResponse<List<ActivityPackageResponse>>> packages(@PathVariable UUID id){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.listPublicPackages(id)));}@GetMapping("/packages/{id}/slots")public ResponseEntity<BaseResponse<List<ActivitySlotResponse>>> slots(@PathVariable UUID id,@RequestParam(required=false)LocalDateTime from){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.listPublicSlots(id,from)));}}
